#!/usr/bin/env bash
# Build dist/jinja.sh: jinja.sh with the awk engine and lib/bash.sh embedded
# (single POSIX sh file). Replaces the blocks between the @jinja-*-begin and
# @jinja-*-end markers of jinja.sh.
set -eu
root=$(cd "${BASH_SOURCE[0]%/*}/.." && pwd)
out=${1:-$root/dist/jinja.sh}
mkdir -p "${out%/*}"
# shellcheck disable=SC1091
source "$root/jinja.sh"

engine() {
	cat <<'EOF'
# awk engine (generated by tools/build.sh from lib/awk/*.awk), on fd 3:
#   _jinja_prog AWK...      run AWK... -f /dev/fd/3
#   _jinja_prog save FILE   copy the program to FILE
_jinja_prog() {
	if [ "$1" = save ]; then
		cat <&3 >"$2"
	else
		LC_ALL=C "$@" -f /dev/fd/3
	fi 3<<'_JINJA_AWK_EOF'
EOF
	for f in $_JINJA_AWK_FILES; do
		# drop comment-only lines and leading indentation to keep it small
		sed -e '/^[[:space:]]*#/d' -e '/^[[:space:]]*$/d' -e 's/^[[:space:]]*//' "$root/lib/awk/$f.awk"
	done
	cat <<'EOF'
_JINJA_AWK_EOF
}

# run the awk command "$@" on the engine; the protocol is on stdin
_jinja_exec() {
	if { [ -r /dev/fd/3 ]; } 3</dev/null 2>/dev/null; then
		_jinja_prog "$@"
		return
	fi
	# no /dev/fd (FreeBSD without fdescfs): go through a temporary file
	_jinja_tmp=$(mktemp "${TMPDIR:-/tmp}/jinja.XXXXXX") || {
		_jinja_err "cannot create a temporary file"
		return
	}
	_jinja_prog save "$_jinja_tmp" && LC_ALL=C "$@" -f "$_jinja_tmp"
	_jinja_rc=$?
	rm -f "$_jinja_tmp"
	return "$_jinja_rc"
}
EOF
}

bash_layer() {
	printf '%s\n' "if [ -n \"\${BASH_VERSION:-}\" ]; then" \
		"	IFS= read -r -d '' _jinja_src <<'_JINJA_BASH_EOF' || :"
	sed -e '/^[[:space:]]*#/d' -e '/^[[:space:]]*$/d' "$root/lib/bash.sh"
	printf '%s\n' "_JINJA_BASH_EOF" "	eval \"\$_jinja_src\"" "	unset _jinja_src" "fi"
}

skip=0
while IFS= read -r line; do
	case $line in
	'# @jinja-engine-begin'*) skip=1 && engine ;;
	'# @jinja-bash-begin'*) skip=1 && bash_layer ;;
	'# @jinja-'*'-end'*) skip=0 ;;
	*) ((skip)) || printf '%s\n' "$line" ;;
	esac
done <"$root/jinja.sh" >"$out"
chmod +x "$out"
printf 'built %s (%d bytes)\n' "$out" "$(wc -c <"$out")"
